import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, uniform } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // Create plane geometry for sprite billboard
  const geometry = new THREE.PlaneGeometry(1, 0.625);

  // Create material with texture map node
  const material = new MeshBasicNodeMaterial();

  // Load the sprite texture and apply it
  const texturePromise = ctx.textureLoader.loadTexture(config.imageUrl);
  texturePromise.then((texture) => {
    // Set up atlas region: 0,0,512,320 means full texture
    texture.magFilter = THREE.LinearFilter;
    texture.minFilter = THREE.LinearMipMapLinearFilter;

    // Apply texture via material
    material.colorNode = texture;
    material.needsUpdate = true;
  });

  // Create mesh
  const mesh = new THREE.Mesh(geometry, material);
  mesh.castShadow = false;
  mesh.receiveShadow = false;

  // Billboard constraint: always face camera (will be updated by parent render loop if needed)
  const group = new THREE.Group();
  group.add(mesh);

  // Setup cleanup
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
  };

  group.userData.handlers = {};

  return group;
}
